<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Setup Ashik ERP</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172b4d;font-family:Arial,sans-serif}.page{min-height:100vh;padding:30px 16px}.wrap{max-width:720px;margin:auto}.brand{text-align:center;margin-bottom:25px}.brand-logo{height:42px;max-width:180px;object-fit:contain;margin:0 auto 10px;display:block}.logo-fallback{width:48px;height:48px;margin:0 auto 10px;border-radius:14px;background:#2563eb;color:#fff;display:grid;place-items:center;font-size:22px;font-weight:700}.brand h1{font-size:22px;margin:0 0 5px}.brand p{font-size:13px;color:#667085;margin:0}.progress{display:flex;align-items:center;justify-content:center;margin-bottom:24px}.circle{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;background:#2563eb;color:#fff}.circle.done{background:#12b76a}.bar{width:85px;height:2px;background:#2563eb}.bar.off{background:#dfe3eb}.card{background:#fff;border:1px solid #e4e7ec;border-radius:14px;padding:28px;box-shadow:0 8px 25px #1018280b}.card h2{font-size:20px;margin:0 0 8px}.intro{color:#667085;font-size:13px;line-height:1.6;margin:0 0 24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.field{margin:0 0 18px}.field.full{grid-column:1/-1}.field label{display:block;font-weight:700;font-size:13px;margin-bottom:7px}.field input{width:100%;padding:12px 13px;border:1px solid #d0d5dd;border-radius:8px;font-size:14px;outline:0}.field input:focus{border-color:#2563eb;box-shadow:0 0 0 3px #2563eb1a}.field small{display:block;color:#667085;font-size:10px;margin-top:5px}.error{color:#b42318;font-size:12px;margin-top:5px}.help{background:#f8fafc;border:1px solid #eef0f4;border-radius:8px;padding:12px;color:#667085;font-size:11px;line-height:1.5;margin-top:2px}.actions{display:flex;gap:10px;margin-top:24px}.button{display:block;text-align:center;text-decoration:none;border:0;border-radius:8px;padding:13px;font-size:13px;font-weight:700;cursor:pointer}.back{background:#f2f4f7;color:#344054;flex:0 0 110px}.finish{background:#2563eb;color:#fff;flex:1}.finish:disabled{background:#98a2b3;cursor:not-allowed}@media(max-width:600px){.page{padding:24px 13px}.card{padding:21px}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.bar{width:45px}.actions{flex-direction:column-reverse}.back,.finish{flex:auto;width:100%}}</style></head><body><main class="page"><div class="wrap"><header class="brand">@if(config('version-updater.logo'))<img class="brand-logo" src="{{ asset(config('version-updater.logo')) }}" alt="{{ config('app.name', 'Ashik ERP') }}">@else<div class="logo-fallback">A</div>@endif<h1>Setup Ashik ERP</h1><p>Almost finished. Enter your system details.</p></header><div class="progress"><span class="circle done">✓</span><span class="bar"></span><span class="circle">2</span><span class="bar off"></span><span class="circle" style="background:#e4e7ec;color:#667085">3</span></div><section class="card"><h2>Application details</h2><p class="intro">Fill in the details below to complete your installation.</p>@if(!$allPassed)<div class="help" style="margin-bottom:20px;background:#fffaeb;border-color:#fedf89;color:#b54708">⚠ Please go back and fix the server checks first.</div>@endif<form method="POST" action="{{ route('ashik.install.store') }}">@csrf<div class="form-grid"><div class="field"><label for="app_name">Application name</label><input id="app_name" name="app_name" value="{{ old('app_name', config('app.name')) }}" placeholder="Example: ApexERP" required><small>Name shown in your system.</small>@error('app_name')<div class="error">{{ $message }}</div>@enderror</div><div class="field"><label for="app_url">Application URL</label><input id="app_url" name="app_url" type="url" value="{{ old('app_url', config('app.url')) }}" placeholder="https://example.com" required><small>Address used to open the system.</small>@error('app_url')<div class="error">{{ $message }}</div>@enderror</div>@if($purchaseCodeRequired)<div class="field full"><label for="purchase_code">Purchase code</label><input id="purchase_code" name="purchase_code" value="{{ old('purchase_code') }}" placeholder="Enter the code given to you" required><small>This code activates this installation.</small>@error('purchase_code')<div class="error">{{ $message }}</div>@enderror</div>@endif</div><div class="help">🔒 Your information is saved in your own database. No existing data will be deleted.</div><div class="actions"><a class="button back" href="{{ route('ashik.install') }}">← Back</a><button class="button finish" type="submit" @disabled(!$allPassed)>Finish setup&nbsp; →</button></div></form></section></div></main></body></html>
